AssistantMessageToolRequest(name='create', tool_call_id='tooluse_NWEil8rEHTxiFX6puBgM2X', arguments={'file_text': "const form = document.getElementById('contactForm');
const fullNameInput = document.getElementById('fullName');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');
const successMessage = document.getElementById('successMessage');

const fullNameError = document.getElementById('fullNameError');
const emailError = document.getElementById('emailError');
const phoneError = document.getElementById('phoneError');

const validateFullName = (value) => {
    if (!value.trim()) {
        return 'Full name is required.';
    }
    if (value.trim().length < 2) {
        return 'Full name must be at least 2 characters.';
    }
    return '';
};

const validateEmail = (value) => {
    if (!value.trim()) {
        return 'Email address is required.';
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) {
        return 'Please enter a valid email address.';
    }
    return '';
};

const validatePhone = (value) => {
    if (!value.trim()) {
        return '';
    }
    const phoneRegex = /^[\d\s\-().+]*$/;
    if (!phoneRegex.test(value)) {
        return 'Phone number contains invalid characters.';
    }
    const digitsOnly = value.replace(/\D/g, '');
    if (digitsOnly.length > 0 && (digitsOnly.length < 10 || digitsOnly.length > 15)) {
        return 'Phone number should contain 10-15 digits.';
    }
    return '';
};

const showError = (input, errorElement, message) => {
    if (message) {
        errorElement.textContent = message;
        input.setAttribute('aria-invalid', 'true');
    } else {
        errorElement.textContent = '';
        input.setAttribute('aria-invalid', 'false');
    }
};

const validateField = (input, errorElement, validator) => {
    const message = validator(input.value);
    showError(input, errorElement, message);
    return !message;
};

fullNameInput.addEventListener('blur', () => {
    validateField(fullNameInput, fullNameError, validateFullName);
});

emailInput.addEventListener('blur', () => {
    validateField(emailInput, emailError, validateEmail);
});

phoneInput.addEventListener('blur', () => {
    validateField(phoneInput, phoneError, validatePhone);
});

fullNameInput.addEventListener('input', () => {
    if (fullNameError.textContent) {
        validateField(fullNameInput, fullNameError, validateFullName);
    }
});

emailInput.addEventListener('input', () => {
    if (emailError.textContent) {
        validateField(emailInput, emailError, validateEmail);
    }
});

phoneInput.addEventListener('input', () => {
    if (phoneError.textContent) {
        validateField(phoneInput, phoneError, validatePhone);
    }
});

form.addEventListener('submit', (e) => {
    e.preventDefault();

    const isFullNameValid = validateField(fullNameInput, fullNameError, validateFullName);
    const isEmailValid = validateField(emailInput, emailError, validateEmail);
    const isPhoneValid = validateField(phoneInput, phoneError, validatePhone);

    if (isFullNameValid && isEmailValid && isPhoneValid) {
        successMessage.textContent = '✓ Your message has been sent successfully! We'll get back to you soon.';
        successMessage.classList.add('show');

        form.reset();
        fullNameError.textContent = '';
        emailError.textContent = '';
        phoneError.textContent = '';

        fullNameInput.setAttribute('aria-invalid', 'false');
        emailInput.setAttribute('aria-invalid', 'false');
        phoneInput.setAttribute('aria-invalid', 'false');

        setTimeout(() => {
            successMessage.classList.remove('show');
        }, 5000);

        fullNameInput.focus();
    } else {
        const firstInvalidInput = [fullNameInput, emailInput, phoneInput].find(
            (input) => input.getAttribute('aria-invalid') === 'true'
        );
        if (firstInvalidInput) {
            firstInvalidInput.focus();
        }
    }
});
