    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

main {
    width: 100%;
}

.container {
    background: white;
    border-radius: 12px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
    padding: 40px;
    max-width: 500px;
    margin: 0 auto;
}

h1 {
    font-size: 28px;
    font-weight: 600;
    color: #1a1a1a;
    margin-bottom: 12px;
}

.intro-text {
    font-size: 16px;
    color: #666;
    margin-bottom: 32px;
    line-height: 1.5;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

label {
    font-size: 14px;
    font-weight: 500;
    color: #1a1a1a;
}

.required {
    color: #dc2626;
    margin-left: 4px;
}

input {
    padding: 12px 14px;
    border: 2px solid #e5e7eb;
    border-radius: 8px;
    font-size: 16px;
    font-family: inherit;
    transition: all 0.2s ease;
    background-color: #fff;
}

input:focus {
    outline: none;
    border-color: #667eea;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

input:focus-visible {
    outline: 2px solid #667eea;
    outline-offset: 2px;
}

input:disabled {
    background-color: #f3f4f6;
    color: #9ca3af;
    cursor: not-allowed;
}

input:invalid:not(:placeholder-shown) {
    border-color: #dc2626;
}

input:invalid:not(:placeholder-shown):focus {
    box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.1);
}

.helper-text {
    font-size: 13px;
    color: #6b7280;
    line-height: 1.4;
}

.error-message {
    font-size: 13px;
    color: #dc2626;
    min-height: 20px;
    line-height: 1.4;
}

.submit-button {
    padding: 12px 24px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: 8px;
}

.submit-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(102, 126, 234, 0.3);
}

.submit-button:active {
    transform: translateY(0);
}

.submit-button:focus-visible {
    outline: 2px solid #667eea;
    outline-offset: 2px;
}

.submit-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
    transform: none;
}

.success-message {
    margin-top: 24px;
    padding: 14px 16px;
    background-color: #d1fae5;
    color: #065f46;
    border-radius: 8px;
    font-size: 14px;
    border: 1px solid #a7f3d0;
    min-height: 0;
    display: none;
}

.success-message.show {
    display: block;
    animation: slideIn 0.3s ease;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (max-width: 600px) {
    .container {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
    }

    input,
    .submit-button {
        font-size: 16px;
    }
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

@media (forced-colors: active) {
    input {
        border-color: CanvasText;
    }

    input:focus {
        outline-color: ButtonText;
    }

    .submit-button {
        background: ButtonFace;
        color: ButtonText;
        border: 2px solid ButtonText;
    }

    .error-message {
        color: CanvasText;
    }
}
